import { execFileSync } from 'node:child_process';
import fs from 'node:fs/promises';

function resolveCommit() {
  const envSha = process.env.GITHUB_SHA?.trim();
  if (envSha) return envSha.slice(0, 8);

  try {
    return execFileSync('git', ['rev-parse', '--short=8', 'HEAD'], {
      encoding: 'utf8'
    }).trim();
  } catch {
    return 'development';
  }
}

const commit = resolveCommit().replaceAll("'", '');
const content =
  '// Generated by scripts/write-build-info.mjs for packaged builds.\n' +
  `export const BUILD_COMMIT = '${commit}';\n`;

await fs.writeFile(new URL('../src/build-info.mjs', import.meta.url), content, 'utf8');
console.log(`Build commit: ${commit}`);
